package onboarding.dto;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class ValidationResult {
    private final boolean valid;
    private final List<ValidationError> errors;

    private ValidationResult(boolean valid, List<ValidationError> errors) {
        this.valid = valid;
        this.errors = Collections.unmodifiableList(new ArrayList<ValidationError>(errors));
    }

    public static ValidationResult valid() {
        return new ValidationResult(true, Collections.<ValidationError>emptyList());
    }

    public static ValidationResult invalid(ValidationError error) {
        if (error == null) {
            throw new IllegalArgumentException("El error es obligatorio.");
        }

        List<ValidationError> errors = new ArrayList<ValidationError>();
        errors.add(error);
        return new ValidationResult(false, errors);
    }

    public boolean isValid() {
        return valid;
    }

    public List<ValidationError> getErrors() {
        return errors;
    }
}
