package onboarding.service;

import onboarding.dto.ValidationError;
import onboarding.dto.ValidationResult;

public final class TestDocumentValidator {
    private static final String FIELD = "documento";

    /**
     * Comprueba únicamente que el valor está presente y usa el prefijo de prueba
     * definido por el alcance. No sustituye la validación completa del contrato.
     */
    public ValidationResult validate(String document) {
        if (document == null || document.trim().isEmpty()) {
            return ValidationResult.invalid(new ValidationError(
                    FIELD,
                    "Completa el documento de prueba para continuar."
            ));
        }

        if (!document.trim().startsWith("TEST-")) {
            return ValidationResult.invalid(new ValidationError(
                    FIELD,
                    "Usa únicamente un documento de prueba que comience con TEST-."
            ));
        }

        return ValidationResult.valid();
    }
}
