package onboarding.service;

import onboarding.model.WalletOutcome;

public final class KycOutcomeMapper {

    /**
     * Solo reconoce los pares de escenario y estado confirmados.
     * Valores nulos, desconocidos o inconsistentes no implican una decisión.
     */
    public WalletOutcome map(String scenario, String status) {
        if ("APPROVED".equals(scenario) && "ACTIVE".equals(status)) {
            return WalletOutcome.WALLET_ACTIVE;
        }

        if ("MANUAL_REVIEW".equals(scenario) && "PENDING".equals(status)) {
            return WalletOutcome.REVIEW_PENDING;
        }

        if ("REJECTED".equals(scenario) && "REJECTED".equals(status)) {
            return WalletOutcome.REJECTED;
        }

        return WalletOutcome.NON_CONCLUSIVE;
    }
}
