        );
        check(
                invalid.getErrors().get(0).getMessage().contains("TEST-"),
                "El error debe explicar cómo corregir el valor."
        );

        KycOutcomeMapper mapper = new KycOutcomeMapper();
        check(
                mapper.map("APPROVED", "ACTIVE") == WalletOutcome.WALLET_ACTIVE,
                "APPROVED/ACTIVE debe mapear a WALLET_ACTIVE."
        );
        check(
                mapper.map("MANUAL_REVIEW", "PENDING") == WalletOutcome.REVIEW_PENDING,
                "MANUAL_REVIEW/PENDING debe mapear a REVIEW_PENDING."
        );
        check(
                mapper.map("APPROVED", "PENDING") == WalletOutcome.NON_CONCLUSIVE,
                "Un par inconsistente debe ser no concluyente."
        );

        System.out.println("OK: casos de validación y mapeo KYC comprobados.");
    }

    private static void check(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
