import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

export const DEMO_OTP = '123456';

export function testDocumentValidator(): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    const value = String(control.value ?? '');

    if (!value.trim()) {
      return { required: true };
    }

    if (!value.trim().startsWith('TEST-')) {
      return { testPrefix: true };
    }

    return null;
  };
}

export function approvedTestPhoneValidator(approvedNumbers: readonly string[]): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    const value = String(control.value ?? '').trim();

    if (!value) {
      return { required: true };
    }

    if (approvedNumbers.length === 0) {
      return { testNumbersNotConfigured: true };
    }

    if (!approvedNumbers.includes(value)) {
      return { testNumberNotAllowed: true };
    }

    return null;
  };
}

export function demoOtpValidator(): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    const value = String(control.value ?? '');

    if (!value.trim()) {
      return { required: true };
    }

    if (!/^\d{6}$/.test(value)) {
      return { otpFormat: true };
    }

    if (value !== DEMO_OTP) {
      return { otpMismatch: true };
    }

    return null;
  };
}
