// src/app/onboarding/onboarding.service.ts
import { Inject, Injectable } from '@angular/core';
import {
  OnboardingEvent,
  ONBOARDING_EVENT_SINK,
  OnboardingEventSink,
} from './onboarding.events';
import {
  KycPair,
  OnboardingDraft,
  OnboardingResult,
  OnboardingStepId,
  WalletOutcome,
} from './onboarding.models';
import {
  KYC_PORT,
  KycPort,
  ONBOARDING_SUBMIT_PORT,
  OnboardingSubmitPort,
} from './onboarding.ports';

export function mapKycOutcome(pair: KycPair): WalletOutcome {
  if (pair.scenario === 'APPROVED' && pair.status === 'ACTIVE') {
    return WalletOutcome.WALLET_ACTIVE;
  }

  if (pair.scenario === 'MANUAL_REVIEW' && pair.status === 'PENDING') {
    return WalletOutcome.REVIEW_PENDING;
  }

  if (pair.scenario === 'REJECTED' && pair.status === 'REJECTED') {
    return WalletOutcome.REJECTED;
  }

  return WalletOutcome.NON_CONCLUSIVE;
}

@Injectable()
export class OnboardingFlowService {
  private startedAt?: number;
  private closed = false;
  private submittedAt?: number;
  private submissionInFlight?: Promise<OnboardingResult>;
  private result?: OnboardingResult;

  private readonly startedSteps = new Set<OnboardingStepId>();
  private readonly completedSteps = new Set<OnboardingStepId>();

  constructor(
    @Inject(ONBOARDING_SUBMIT_PORT)
    private readonly submitPort: OnboardingSubmitPort,
    @Inject(KYC_PORT)
    private readonly kycPort: KycPort,
    @Inject(ONBOARDING_EVENT_SINK)
    private readonly eventSink: OnboardingEventSink,
  ) {}

  get canSubmit(): boolean {
    return this.submitPort.isConfigured() && !this.closed;
  }

  start(): void {
    if (this.startedAt !== undefined || this.closed) {
      return;
    }

    this.startedAt = Date.now();
    this.emit({ name: 'onboarding_started' });
    this.startStep('document');
  }

  startStep(stepId: OnboardingStepId): void {
    if (this.closed || this.startedSteps.has(stepId)) {
      return;
    }

    this.ensureStarted();
    this.startedSteps.add(stepId);
    this.emit({ name: 'onboarding_step_started', stepId });
  }

  completeStep(stepId: OnboardingStepId): void {
    if (this.closed || this.completedSteps.has(stepId)) {
      return;
    }

    this.ensureStarted();
    this.completedSteps.add(stepId);
    this.emit({ name: 'onboarding_step_completed', stepId });
  }

  close(): void {
    if (this.closed) {
      return;
    }

    this.ensureStarted();
    this.closed = true;
    this.emit({ name: 'onboarding_closed', closeReason: 'voluntary' });
  }

  async submitAndResolveKyc(draft: OnboardingDraft): Promise<OnboardingResult> {
    if (this.result) {
      return this.result;
    }

    if (this.submissionInFlight) {
      return this.submissionInFlight;
    }

    if (!this.canSubmit) {
      throw new Error('El adaptador aprobado de envío no está configurado.');
    }

    const operation = this.performSubmission(draft);
    this.submissionInFlight = operation;

    try {
      return await operation;
    } finally {
      if (this.submissionInFlight === operation) {
        this.submissionInFlight = undefined;
      }
    }
  }

  private async performSubmission(draft: OnboardingDraft): Promise<OnboardingResult> {
    this.ensureStarted();

    // El contrato real y el adaptador deben definir el mapeo de este borrador.
    // El OTP no forma parte de los datos enviados.
    await this.submitPort.submit(draft);

    this.submittedAt = Date.now();
    this.emit({
      name: 'onboarding_submission_succeeded',
      elapsedMs: this.elapsedSinceStart(),
    });

    let outcome = WalletOutcome.NON_CONCLUSIVE;

    if (this.kycPort.isConfigured()) {
      try {
        const pair = await this.kycPort.evaluate();
        outcome = mapKycOutcome(pair);
      } catch {
        // Una falla o respuesta no disponible no implica aprobación ni rechazo.
        outcome = WalletOutcome.NON_CONCLUSIVE;
      }
    }

    this.result = { outcome };
    this.emit({ name: 'onboarding_kyc_result', outcome });

    if (outcome === WalletOutcome.WALLET_ACTIVE) {
      this.emit({
        name: 'onboarding_wallet_activated',
        elapsedMs: this.elapsedSinceStart(),
        sinceSubmissionMs: Math.max(0, Date.now() - this.submittedAt),
        outcome,
      });
    }

    return this.result;
  }

  private ensureStarted(): void {
    if (this.startedAt === undefined) {
      this.start();
    }
  }

  private elapsedSinceStart(): number {
    return this.startedAt === undefined
      ? 0
      : Math.max(0, Date.now() - this.startedAt);
  }

  private emit(
    event: Omit<OnboardingEvent, 'at'>,
  ): void {
    this.eventSink.record({ ...event, at: Date.now() });
  }
}
