```typescript
// src/app/onboarding/onboarding.component.ts
import { CommonModule } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { AbstractControl, FormBuilder, ReactiveFormsModule } from '@angular/forms';
import {
  ONBOARDING_STEPS,
  OnboardingStepId,
  WalletOutcome,
} from './onboarding.models';
import {
  approvedTestPhoneValidator,
  demoOtpValidator,
  testDocumentValidator,
} from './onboarding.rules';
import { TEST_PHONE_NUMBERS } from './onboarding.ports';
import { OnboardingFlowService } from './onboarding.service';

@Component({
  selector: 'app-onboarding',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './onboarding.component.html',
  styleUrls: ['./onboarding.component.scss'],
  providers: [OnboardingFlowService],
})
export class OnboardingComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly approvedTestNumbers = inject(TEST_PHONE_NUMBERS);

  readonly flow = inject(OnboardingFlowService);
  readonly steps = ONBOARDING_STEPS;

  readonly form = this.fb.nonNullable.group({
    documento: ['', [testDocumentValidator()]],
    celular: ['', [approvedTestPhoneValidator(this.approvedTestNumbers)]],
    otp: ['', [demoOtpValidator()]],
  });

  currentIndex = 0;
  submittedStep = false;
  otpVerifiedLocally = false;
  busy = false;
  closed = false;
  submitError = '';
  result?: WalletOutcome;

  ngOnInit(): void {
    this.flow.start();
  }

  get currentStep(): OnboardingStepId {
    return this.steps[this.currentIndex].id;
  }

  get documento(): AbstractControl {
    return this.form.controls.documento;
  }

  get celular(): AbstractControl {
    return this.form.controls.celular;
  }

  get otp(): AbstractControl {
    return this.form.controls.otp;
  }

  showError(control: AbstractControl): boolean {
    return control.invalid && (control.touched || this.submittedStep);
  }

  errorMessage(control: AbstractControl): string {
    if (!this.showError(control)) {
      return '';
    }

    if (control.hasError('required')) {
      return 'Completa este campo para continuar.';
    }

    if (control.hasError('testPrefix')) {
      return 'Usa únicamente un documento de prueba que comience con TEST-.';
    }

    if (control.hasError('testNumbersNotConfigured')) {
      return 'El catálogo de celulares de prueba no está configurado. No uses un número real.';
    }

    if (control.hasError('testNumberNotAllowed')) {
      return 'Ese celular no figura en el catálogo autorizado de pruebas. Usa uno configurado para TEST.';
    }

    if (control.hasError('otpFormat')) {
      return 'Ingresa los seis dígitos del código de demo: 123456.';
    }

    if (control.hasError('otpMismatch')) {
      return 'El código de demo no es correcto. Ingresa 123456.';
    }

    return 'Revisa este dato para continuar.';
  }

  continue(): void {
    this.submittedStep = true;

    if (this.currentIndex === 0) {
      this.documento.markAsTouched();

      if (this.documento.invalid) {
        this.focusFirstInvalid();
        return;
      }

      this.flow.completeStep('document');
      this.currentIndex = 1;
      this.submittedStep = false;
      this.flow.startStep('phone_otp');
      return;
    }

    if (this.currentIndex === 1) {
      this.celular.markAsTouched();
      this.otp.markAsTouched();

      if (this.celular.invalid || this.otp.invalid) {
        this.focusFirstInvalid();
        return;
      }

      // Esta comprobación local del código no verifica la titularidad del celular.
      this.otpVerifiedLocally = true;
      this.flow.completeStep('phone_otp');
      this.currentIndex = 2;
      this.submittedStep = false;
      this.flow.startStep('review');
    }
  }

  back(): void {
    if (this.currentIndex > 0 && !this.busy && !this.result) {
      this.currentIndex -= 1;
      this.submittedStep = false;
    }
  }

  async submit(): Promise<void> {
    if (this.busy || this.result) {
      return;
    }

    if (!this.flow.canSubmit) {
      this.submitError =
        'El envío está bloqueado porque falta configurar el adaptador aprobado. Tus datos no se han enviado.';
      return;
    }

    this.busy = true;
    this.submitError = '';

    try {
      const response = await this.flow.submitAndResolveKyc({
        documento: this.form.controls.documento.value,
        celular: this.form.controls.celular.value.trim(),
      });

      this.result = response.outcome;
      this.flow.completeStep('review');
    } catch {
      this.submitError =
        'No se pudieron enviar los datos de prueba. Se conservaron para que puedas reintentar cuando el servicio esté disponible.';
    } finally {
      this.busy = false;
    }
  }

  closeFlow(): void {
    this.flow.close();
    this.closed = true;
  }

  resultMessage(): string {
    switch (this.result) {
      case WalletOutcome.WALLET_ACTIVE:
        return 'Wallet activa según el resultado de onboarding del mock. Esto no habilita operaciones financieras reales.';
      case WalletOutcome.REVIEW_PENDING:
        return 'La revisión KYC está pendiente. No es una aprobación ni significa que la wallet esté activa.';
      case WalletOutcome.REJECTED:
        return 'El resultado de onboarding del mock es rechazo.';
      case WalletOutcome.NON_CONCLUSIVE:
        return 'No hay un resultado KYC concluyente. No se infiere aprobación ni activación.';
      default:
        return '';
    }
  }

  private focusFirstInvalid(): void {
    setTimeout(() => {
      document
        .querySelector<HTMLElement>('[aria-invalid="true"]')
        ?.focus();
    });
  }
}
