    submitPort.submit.and.returnValue(Promise.resolve());
    kycPort.isConfigured.and.returnValue(true);
    kycPort.evaluate.and.returnValue(
      Promise.resolve({ scenario: 'APPROVED', status: 'ACTIVE' }),
    );

    TestBed.configureTestingModule({
      providers: [
        OnboardingFlowService,
        { provide: ONBOARDING_SUBMIT_PORT, useValue: submitPort },
        { provide: KYC_PORT, useValue: kycPort },
        { provide: ONBOARDING_EVENT_SINK, useValue: sink },
      ],
    });

    service = TestBed.inject(OnboardingFlowService);
  });

  afterEach(() => TestBed.resetTestingModule());

  it('registra inicio, pasos, envío exitoso y activación por separado', async () => {
    service.start();
    service.completeStep('document');
    service.startStep('phone_otp');
    service.completeStep('phone_otp');
    service.startStep('review');

    const result = await service.submitAndResolveKyc(draft);
    service.completeStep('review');

    expect(result.outcome).toBe(WalletOutcome.WALLET_ACTIVE);
    expect(submitPort.submit).toHaveBeenCalledTimes(1);
    expect(kycPort.evaluate).toHaveBeenCalledTimes(1);
    expect(sink.events.map((event) => event.name)).toContain('onboarding_started');
    expect(sink.events.map((event) => event.name)).toContain('onboarding_step_completed');
    expect(sink.events.map((event) => event.name)).toContain('onboarding_submission_succeeded');
    expect(sink.events.map((event) => event.name)).toContain('onboarding_kyc_result');
    expect(sink.events.map((event) => event.name)).toContain('onboarding_wallet_activated');

    const submission = sink.events.find(
      (event) => event.name === 'onboarding_submission_succeeded',
    );
    const activation = sink.events.find(
      (event) => event.name === 'onboarding_wallet_activated',
    );

    expect(submission?.elapsedMs).toBeDefined();
    expect(activation?.sinceSubmissionMs).toBeDefined();
    expect(JSON.stringify(sink.events)).not.toContain(draft.documento);
    expect(JSON.stringify(sink.events)).not.toContain(draft.celular);
    expect(JSON.stringify(sink.events)).not.toContain('123456');
  });

  it('evita envíos duplicados simultáneos', async () => {
    let resolveSubmit!: () => void;
    submitPort.submit.and.returnValue(
      new Promise<void>((resolve) => {
        resolveSubmit = resolve;
      }),
    );

    const first = service.submitAndResolveKyc(draft);
    const second = service.submitAndResolveKyc(draft);

    expect(submitPort.submit).toHaveBeenCalledTimes(1);
    resolveSubmit();

    const [firstResult, secondResult] = await Promise.all([first, second]);
    expect(firstResult).toEqual(secondResult);
    expect(kycPort.evaluate).toHaveBeenCalledTimes(1);
  });

  it('no registra envío exitoso cuando falla el adaptador', async () => {
    submitPort.submit.and.returnValue(Promise.reject(new Error('fallo de prueba')));

    await expectAsync(service.submitAndResolveKyc(draft)).toBeRejected();

    expect(
      sink.events.some((event) => event.name === 'onboarding_submission_succeeded'),
    ).toBeFalse();
    expect(kycPort.evaluate).not.toHaveBeenCalled();
  });

  it('registra cierre voluntario una sola vez', () => {
    service.start();
    service.close();
    service.close();

    const closeEvents = sink.events.filter(
      (event) => event.name === 'onboarding_closed',
    );

    expect(closeEvents.length).toBe(1);
    expect(closeEvents[0].closeReason).toBe('voluntary');
  });

  it('mantiene resultado no concluyente si el mock KYC no está configurado', async () => {
    kycPort.isConfigured.and.returnValue(false);

    const result = await service.submitAndResolveKyc(draft);

    expect(result.outcome).toBe(WalletOutcome.NON_CONCLUSIVE);
    expect(kycPort.evaluate).not.toHaveBeenCalled();
  });
});
